// Writes the NCERT catalogue rows into a migration, between the markers
//   -- BEGIN ncert catalogue (generated by scripts/ncert/build-migration.ts)
//   -- END ncert catalogue
// as one upsert on `code`, so a later refresh is a NEW migration with the
// same two markers (never an edit of a merged one).
//
//   node scripts/ncert/build-migration.ts supabase/migrations/<file>.sql [catalogue.json]
//
// The catalogue (scripts/ncert/ncert-catalogue.json) holds metadata and
// official URLs only; nothing here fetches or stores NCERT PDF content.
import fs from "node:fs";
import path from "node:path";

const BEGIN = "-- BEGIN ncert catalogue (generated by scripts/ncert/build-migration.ts)";
const END = "-- END ncert catalogue";

interface Book {
  class: number | string;
  subject: string;
  title: string;
  medium: string;
  code: string;
  chapters_count: number;
  book_url: string;
  chapter_pdf_pattern: string;
  prelims_pdf: string | null;
  verified: boolean;
}

const sqlText = (value: string | null): string => (value === null ? "null" : `'${value.replace(/'/g, "''")}'`);

function classOf(value: number | string): { label: string; level: number | null } {
  if (typeof value === "number" && Number.isInteger(value) && value >= 1 && value <= 12) return { label: String(value), level: value };
  if (value === "11-12 combined") return { label: "11-12", level: null };
  throw new Error(`Unknown class value: ${JSON.stringify(value)}`);
}

export function buildCatalogueSql(books: readonly Book[], retrievedOn: string): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(retrievedOn)) throw new Error(`Bad retrieved_on: ${retrievedOn}`);
  const rows = books.map((b) => {
    const { label, level } = classOf(b.class);
    if (!Number.isInteger(b.chapters_count)) throw new Error(`Bad chapters_count for ${b.code}`);
    return `  (${[
      sqlText(b.code),
      sqlText(label),
      level === null ? "null" : String(level),
      sqlText(b.subject.trim()),
      sqlText(b.title.trim()),
      sqlText(b.medium),
      String(b.chapters_count),
      sqlText(b.book_url),
      sqlText(b.chapter_pdf_pattern),
      sqlText(b.prelims_pdf ?? null),
      b.verified === true ? "true" : "false",
      `'${retrievedOn}'`,
    ].join(", ")})`;
  });
  return [
    BEGIN,
    `-- ${books.length} rows from ncert.nic.in/textbook.php, retrieved ${retrievedOn}.`,
    "insert into public.ncert_textbooks (code, class_label, class_level, subject, title, medium, chapters_count, book_url, chapter_pdf_pattern, prelims_pdf, verified, retrieved_on) values",
    `${rows.join(",\n")}`,
    "on conflict (code) do update set",
    "  class_label = excluded.class_label, class_level = excluded.class_level, subject = excluded.subject, title = excluded.title,",
    "  medium = excluded.medium, chapters_count = excluded.chapters_count, book_url = excluded.book_url,",
    "  chapter_pdf_pattern = excluded.chapter_pdf_pattern, prelims_pdf = excluded.prelims_pdf, verified = excluded.verified,",
    "  retrieved_on = excluded.retrieved_on;",
    END,
  ].join("\n");
}

function main(): void {
  const [target, cataloguePath = path.join(import.meta.dirname, "ncert-catalogue.json")] = process.argv.slice(2);
  if (!target) {
    console.error("Usage: node scripts/ncert/build-migration.ts <migration.sql> [catalogue.json]");
    process.exit(1);
  }
  const catalogue = JSON.parse(fs.readFileSync(cataloguePath, "utf8")) as { retrieved_on: string; books: Book[] };
  const migration = fs.readFileSync(target, "utf8");
  const start = migration.indexOf(BEGIN);
  const end = migration.indexOf(END);
  if (start < 0 || end < start) throw new Error(`Markers not found in ${target}`);
  const out = migration.slice(0, start) + buildCatalogueSql(catalogue.books, catalogue.retrieved_on) + migration.slice(end + END.length);
  fs.writeFileSync(target, out);
  console.log(`Wrote ${catalogue.books.length} catalogue rows into ${target}`);
}

if (process.argv[1]?.endsWith("build-migration.ts")) main();
